mapper.sql:
WHERE company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})


        AND status = #{filter.status}


        AND status > 0


AND balance > 0
AND location_group_id IN (SELECT location_group_id FROM user_location_groups WHERE user_id = #{userId})

    AND (
        so_code LIKE CONCAT('%', #{filter.searchText}, '%')
        OR customers.name LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND order_date <= #{filter.date}


    AND created_by = #{filter.createdBy}


    AND company_id = #{filter.companyId}


    AND location_group_id = #{filter.warehouseId}


    AND customer_id = #{filter.organizationId}


    AND customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.organizationGroupId})
